import org.springframework.batch.item.database.JdbcBatchItemWriter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableBatchProcessing
public class BatchConfig {

    @Autowired
    public JobBuilderFactory jobBuilderFactory;

    @Autowired
    public StepBuilderFactory stepBuilderFactory;

    @Bean
    public JdbcCursorItemReader<User> userItemReader() {
        JdbcCursorItemReader<User> reader = new JdbcCursorItemReader<>();
        reader.setDataSource(dataSource());
        reader.setSql("SELECT id, name, email FROM users");
        reader.setRowMapper((rs, rowNum) -> new User(rs.getInt("id"), rs.getString("name"), rs.getString("email")));
        return reader;
    }

    @Bean
    public JdbcBatchItemWriter<User> userItemWriter() {
        JdbcBatchItemWriter<User> writer = new JdbcBatchItemWriter<>();
        writer.setDataSource(dataSource());
        writer.setItemSqlParameterSourceProvider(new BeanPropertyItemSqlParameterSourceProvider<>());
        writer.setSql("INSERT INTO processed_users (id, name, email) VALUES (:id, :name, :email)");
        writer.setQualifier("userItemWriter");
        return writer;
    }

    @Bean
    public Step userStep() {
        return stepBuilderFactory.get("userStep")
                .<User, User>chunk(10)
                .reader(userItemReader())
                .writer(userItemWriter())
                .build();
    }

    @Bean
    public Job userJob() {
        return jobBuilderFactory.get("userJob")
                .start(userStep())
                .build();
    }
}
```

In this example:
- `JdbcCursorItemReader` reads data from a database.
- `JdbcBatchItemWriter` writes data into another table.
- A simple `chunk` processing strategy is used where items are read and written in batches of 10.

