```cpp
#include <iostream>
using namespace std;

// Node structure for the singly linked list
struct Node {
    int data;
    Node* next;
};

// Function to create a new node with given data
Node* createNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the beginning of the linked list
void insertAtBeginning(Node** head, int data) {
    Node* newNode = createNode(data);
    newNode->next = *head;
    *head = newNode;
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        cout << current->data << " ";
        current = current->next;
    }
    cout << "\n";
}

// Function to delete a node with a given key from the linked list
void deleteNode(Node** head, int key) {
    Node* temp = *head;
    Node* prev = NULL;

    // If head node itself holds the key to be deleted
    if (temp != NULL && temp->data == key) {
        *head = temp->next;  // Change head
        delete temp;         // Free old head
        return;
    }

    // Search for the key to be deleted, keep track of the previous node as we need to change 'next'
    while (temp != NULL && temp->data != key) {
        prev = temp;
        temp = temp->next;
    }

    // If key was not present in linked list
    if (temp == NULL) return;

    // Unlink the node from linked list
    prev->next = temp->next;

    // Free memory
    delete temp;
}

// Main function
int main() {
    Node* head = NULL;

    // Inserting elements
    insertAtBeginning(&head, 3);
    insertAtBeginning(&head, 2);
    insertAtBeginning(&head, 1);

    cout << "Linked List: ";
    printList(head);

    // Deleting a node
    int key = 2;
    cout << "Deleting node with key " << key << endl;
    deleteNode(&head, key);

    cout << "Updated Linked List: ";
    printList(head);

    return 0;
}
```

### Explanation:
1. **Node Structure**: The `Node` struct defines each node in the linked list. Each node contains an integer `data` and a pointer `next` to the next node in the list.
2. **createNode**: A function that creates a new node with the given data and returns a pointer to it.
3. **insertAtBeginning**: Inserts a new node at the beginning of the linked list.
4. **printList**: Prints all the nodes in the linked list.
5. **deleteNode**: Deletes a node with a specific key from the linked list.

