   Use the `FadeThroughTransition` widget to create a fade-in effect when navigating between routes.

Here's a complete example:

### pubspec.yaml
Make sure you have the `flutter_transitions` package added as shown above.

### main.dart
```dart
import 'package:flutter/material.dart';
import 'package:flutter_transitions/flutter_transitions.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Flutter Demo',
      theme: ThemeData(
        primarySwatch: Colors.blue,
      ),
      initialRoute: '/',
      onGenerateRoute: (settings) {
        // Define your routes here
        switch (settings.name) {
          case '/':
            return MaterialPageRoute(
              builder: (_) => HomePage(),
            );
          case '/second':
            return FadeThroughPageRoute(
              builder: (_) => SecondPage(),
            );
          default:
            return MaterialPageRoute(builder: (_) => ErrorPage());
        }
      },
    );
  }
}

class HomePage extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Home Page')),
