// Load the Scripting Addition for Microsoft Edge
var MicrosoftEdge = Application("MicrosoftEdge");

// Check if Microsoft Edge is already running
if (!MicrosoftEdge.isRunning()) {
    // Open Microsoft Edge
    MicrosoftEdge.launch();
}

// Wait until Microsoft Edge is fully launched
