    const int N = 8192; // Length of the vectors
    const int nBytes = N * sizeof(int); // Size in bytes for each vector

    // Allocate host memory
    int *h_a, *h_b, *h_c;
    h_a = new int[N];
    h_b = new int[N];
    h_c = new int[N];

