import std.concurrency;

void sayHello(string name) {
    writeln("Hello, ", name);
}

void main() {
    auto thread = new Thread(&sayHello, "World");
    thread.start();
    thread.join();

    writeln("End of main");
}
```

### 4. Performance Considerations

- **Inline Functions**: Use `inline` where appropriate to reduce function call overhead.

```d
inline void increment(ref int value) {
    value += 1;
}

void main() {
    int x = 0;
    increment(x);
    writeln(x); // Outputs 1
}
