            for (y in 0 until img1.height) {
                for (x in 0 until img1.width) {
                    if (img1.getRGB(x, y) != img2.getRGB(x, y)) {
                        mismatchedPixels++
                    }
                }
            }

            // Set a threshold for how many pixels can differ to still consider the images as the same
            mismatchedPixels <= 10 // You can adjust this threshold as needed
        }
    } catch (e: IOException) {
        println("Error reading image files: ${e.message}")
        false
    }
}

